package com.ke.ticketsystemke.storage;import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import java.io.*;import java.nio.file.*;import static org.assertj.core.api.Assertions.*;
class FilesystemWarrantyFileStorageTest{@TempDir Path root;@Test void storesGeneratedKeyAndChecksumWithoutUsingFilename()throws Exception{var s=new FilesystemWarrantyFileStorage(true,root.toString());var stored=s.store(7L,new ByteArrayInputStream("private evidence".getBytes()));assertThat(stored.key()).startsWith("claims/7/").doesNotContain("evidence");assertThat(s.exists(stored.key())).isTrue();assertThat(stored.checksum()).hasSize(64);assertThat(s.resolvedPath(stored.key())).startsWith(root);}@Test void rejectsTraversal(){var s=new FilesystemWarrantyFileStorage(true,root.toString());assertThatThrownBy(()->s.resolvedPath("../../etc/passwd")).isInstanceOf(IllegalArgumentException.class);}@Test void disabledProviderFailsClosed(){var s=new FilesystemWarrantyFileStorage(false,"");assertThatThrownBy(()->s.store(1L,new ByteArrayInputStream(new byte[]{1}))).isInstanceOf(IllegalStateException.class);}}
